"""Kaggle entry for Model D training.

Unpacks the committed sources and runs scripts/train_d.py.
The embedded bytes must stay identical to those files.
Weights are not embedded. GPU and internet are requested in kernel-metadata.json.
"""

from __future__ import annotations

import base64
import hashlib
import os
import runpy
import sys
import tempfile
from pathlib import Path

PAYLOAD = {
    'src/dl4stg/__init__.py': ('7b882927241859f0a45ace53e3a0e2feb3779efa023eaef239fed3d9602e592b', 'IiIiREw0U1RHIEFzc2lnbm1lbnQgMiBwYWNrYWdlLiIiIg0K'),
    'src/dl4stg/convlstm.py': ('579e7b55457a4181b6ba4d7277b8fbf2d848cabbd22a6194709117ba20b0e8fd', ''),
    'src/dl4stg/data.py': ('fae22151a60215fbf80135feb56ba42e1ac52a5b66cdaf054907d12eac6f5093', ''),
    'src/dl4stg/metrics.py': ('773b53ac706addcb226148d5edcdca833bff86af9252bb8ba38ebf099f7e4904', ''),
    'src/dl4stg/model_a.py': ('18441b612aa557f840ad762050533ce5399fe673d5f4a931ddc196d870d1da96', ''),
    'src/dl4stg/model_d.py': ('a92d98e5cdd1b768369d98c055b7e020c15aa1fca43832d22a143c3f92cd2388', ''),
    'src/dl4stg/transforms.py': ('41c6a92a9670794cbc16f80f95260bea610f674b5b31ca8ae1c75b5e4caa4bf4', ''),
    'src/dl4stg/windows.py': ('7fe60e16d5ec61e4a7d01193f19d4feff840cbf80dd065b590367791efe331e6', ''),
    'scripts/train_d.py': ('ab73dd91a6c399b22bc141d59dbe5e4ce19f9ce915b5f78d56dd61f47d20c2fb', ''),
}


def main() -> None:
    dest = Path(tempfile.mkdtemp(prefix="dl4stg_train_d_"))
    for rel, (digest, b64) in PAYLOAD.items():
        if rel.endswith(".pt") or "weights" in rel.split("/"):
            raise RuntimeError(f"Weights must not be embedded: {rel}")
        raw = base64.b64decode(b64)
        got = hashlib.sha256(raw).hexdigest()
        if got != digest:
            raise RuntimeError(f"{rel} sha256 {got} != {digest}")
        path = dest / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(raw)
        print(f"unpacked {rel} sha256 {got}", flush=True)
    (dest / "figures").mkdir()
    (dest / "results").mkdir()
    (dest / "weights").mkdir()
    working = Path("/kaggle/working")
    if working.is_dir():
        os.chdir(working)
    sys.path.insert(0, str(dest / "src"))
    script = dest / "scripts" / "train_d.py"
    runpy.run_path(str(script), run_name="__main__")


if __name__ == "__main__":
    main()
